using System;using System.IO;using System.Reflection;using UnityEngine;using UnityEditor;using FlyEditor.Flight;
namespace FlyEditor.Editor {
public static class FoldAssistVerification {
 static void Check(bool ok,string text){if(!ok)throw new Exception("[FoldAssist] "+text);}
 static readonly MethodInfo Suggest=typeof(PaperSheet).Assembly.GetType("FlyEditor.Flight.PaperFoldAssist").GetMethod("TryFlanks",BindingFlags.Static|BindingFlags.Public);
 public static bool Try(PaperSheet s,int anchor,Vector2 t,Vector2 h,out FoldStep step){var args=new object[]{s,new PaperSheet.FoldVertex(anchor,t),new PaperSheet.FoldVertex(anchor,h),null,null};step=default;if(!(bool)Suggest.Invoke(null,args))return false;var a=(PaperSheet.FoldVertex)args[3];var b=(PaperSheet.FoldVertex)args[4];var basis=s.Faces[anchor];Vector2 Local(PaperSheet.FoldVertex v){var p=basis.material.inverse.MultiplyPoint3x4(s.Faces[v.anchor].material.MultiplyPoint3x4(new Vector3(v.point.x,0,v.point.y)));return new Vector2(p.x,p.z);}step=new FoldStep{anchor=anchor,flap=anchor+1,cornerPull=true,customFlanks=true,flexible=true,closeFlat=true,exactSquash=true,regionalPull=true,coupledHinges=true,coordinatedCreases=true,adaptiveCreases=true,connectedPetalBacking=true,partialPetalBacking=true,compactLayers=true,pullTip=t,pullStop=h,pullLeft=Local(a),pullRight=Local(b)};return true;}
 [MenuItem("Tools/FlyEditor/Validation/Fold handle assistance")]
 public static void Run(){var root=Environment.GetEnvironmentVariable("FLYEDITOR_LILY")??Path.GetFullPath(Path.Combine(Application.dataPath,"../../Docs/OrigamiAudit/lily-study"));var recipe=JsonUtility.FromJson<ResearchSave>(File.ReadAllText(Path.Combine(root,"partial.json"))).paperFolds;int cases=0;
 foreach(int index in new[]{4,5,7,10,15}){var prefix=new FoldStep[index];Array.Copy(recipe,prefix,index);var s=PaperSheet.Replay(prefix);var old=recipe[index];var before=s.Faces;var timer=System.Diagnostics.Stopwatch.StartNew();bool found=Try(s,old.anchor,old.pullTip,old.pullStop,out var step);timer.Stop();Debug.Log("[AssistProbe] at="+index+" found="+found+" ms="+timer.ElapsedMilliseconds);Check(found,"No suggestion at step "+index);Check(ReferenceEquals(before,s.Faces)&&s.Count==index,"Suggestion changed sheet");var p=PaperCornerPull.Create(s,step);Debug.Log("[AssistProbe] solver squash="+p.UsesExactSquash+" petal="+p.UsesPetalFold+" left="+step.pullLeft+" right="+step.pullRight);int sign=p.Pose(5)?1:-1;bool full=true;for(int a=0;a<=180;a+=15){if(!p.Pose(sign*a)){full=false;Debug.Log("[AssistProbe] blocked at="+a);break;}ReverseDirectionVerification.Geometry(p.Preview);}if(full){Check(s.FinishPull(p,sign*180),"commit");PetalFoldingVerification.Replay(s);Check(s.Undo()&&ReferenceEquals(before,s.Faces),"undo");cases++;}}
 Check(cases==5,"Not all selected folds reached full contact");
 var empty=new PaperSheet();Check(!Try(empty,0,Vector2.zero,Vector2.zero,out _),"Coincident input accepted");Check(!Try(empty,0,new Vector2(-2,-2),Vector2.one,out _),"Off-paper input accepted");Check(empty.Count==0,"Failure changed paper");
 Debug.Log("[FoldAssist] PASS 4 closed pockets and 1 petal: 65 sweep poses, suggestion without mutation, commit/replay/undo; coincident and off-paper input rejected.");
 }
}}
